package test;

import org.eclipse.ui.ISharedImages;
import org.eclipse.jface.resource.ImageDescriptor;

public class TestClass {
    public void setup(ISharedImages workbenchImages) {
        ImageDescriptor disabledImageDescriptor = workbenchImages.getImageDescriptor(ISharedImages.IMG_TOOL_DELETE_DISABLED);
        ImageDescriptor imageDescriptor = workbenchImages.getImageDescriptor(ISharedImages.IMG_TOOL_DELETE);
        ImageDescriptor hoverImageDescriptor = workbenchImages.getImageDescriptor(ISharedImages.IMG_TOOL_DELETE);
        System.out.println(disabledImageDescriptor);
        System.out.println(imageDescriptor);
        System.out.println(hoverImageDescriptor);
    }
}

